// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address actor, address newOwner) public {
        // Step 1: make the fuzzed actor the current owner (admissible for any actor).
        vm.prank(c.owner());
        c.setOwner(actor);
        vm.assume(c.owner() == actor);

        // Step 2: owner calls setOwner to a fuzzed new owner.
        bool ok;
        vm.prank(actor);
        try c.setOwner(newOwner) { ok = true; } catch { ok = false; }

        // Step 3: general rule — the owner can always set a new owner and it takes effect.
        assertTrue(ok && c.owner() == newOwner);
    }
}
